<script setup lang="ts">import{Head,Link,useForm}from'@inertiajs/vue3';import AuthenticatedLayout from'../../Layouts/AuthenticatedLayout.vue';const breadcrumbs=[{label:'BYL ERP',href:'/dashboard'},{label:'库存',href:'/inventory'},{label:'仓库清单',href:'/inventory/list'},'增加仓库'];const form=useForm({slug:'',code:'',name:'',country_code:'',address_line1:'',address_line2:'',city:'',state_region:'',postal_code:'',timezone:'',type:'warehouse',ownership_type:'owned',is_active:true,priority:100,fulfillment_available_on:''});const submit=()=>form.post('/inventory')</script>
<template><Head title="增加仓库 · BYL ERP"/><AuthenticatedLayout title="增加仓库" :breadcrumbs="breadcrumbs"><section class="mvp-page"><div class="mvp-page-heading"><div><p class="mvp-kicker">Warehouse Master</p><h2>增加仓库</h2><p>真实地址未知时请留空，不要填写猜测值。</p></div><div class="mvp-form-actions page-header-actions"><Link class="mvp-button" href="/inventory/list">取消</Link><Link class="mvp-button" href="/inventory/list">返回列表</Link><button type="submit" form="warehouse-create-form" class="mvp-button mvp-button-primary" :disabled="form.processing">创建仓库</button></div></div><form id="warehouse-create-form" class="mvp-card form" @submit.prevent="submit"><div class="grid"><label>仓库名称<input v-model="form.name" required></label><label>仓库代码<input v-model="form.code" required></label><label>URL Slug<input v-model="form.slug" required placeholder="例如 us-la"></label><label>国家代码<input v-model="form.country_code" maxlength="2" placeholder="US"></label><label>地址 1<input v-model="form.address_line1"></label><label>地址 2<input v-model="form.address_line2"></label><label>城市<input v-model="form.city"></label><label>州/省<input v-model="form.state_region"></label><label>邮编<input v-model="form.postal_code"></label><label>时区<input v-model="form.timezone" placeholder="America/Los_Angeles"></label><label>仓库归属<select v-model="form.ownership_type"><option value="owned">自有仓</option><option value="external">外部仓</option></select></label><label>优先级<input v-model.number="form.priority" type="number" min="0"></label><label>预计可发货日期<input v-model="form.fulfillment_available_on" type="date"><small>日期未到前禁止自动分仓；日期到后仍需 Full Snapshot。</small></label><label>状态<select v-model="form.is_active"><option :value="true">启用</option><option :value="false">停用</option></select></label></div></form></section></AuthenticatedLayout></template>
<style scoped>.form{max-width:1000px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.grid label{display:flex;flex-direction:column;gap:6px;font-size:13px}.grid input,.grid select{padding:10px;border:1px solid #dbe2e8;border-radius:8px}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style>
